import { useState } from 'react';
import { Combobox, type ListboxOption } from '@design-schema/react';

const FRUITS: ListboxOption[] = [
  { value: 'apple', label: 'Apple' },
  { value: 'apricot', label: 'Apricot' },
  { value: 'banana', label: 'Banana' },
];

function Example() {
  const [open, setOpen] = useState(true ?? true);
  return (
    <Combobox
      label="Fruit"
      name="fruit"
      options={FRUITS}
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        undefined?.(next);
      }}
    />
  );
}

<Example />

